"""Add original browser-capability and mobile-layout lessons to local drafts."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def paragraph(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    title = by_path[path]['title'] if path in by_path else next((item['title'] for item in topics if item['path'] == path), None)
    assert title is not None, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(title) + '</a>'

hubs = [
    ('web-tech/browser-capabilities-and-permission-lifecycle', 'Browser Capabilities and Permission Lifecycle', 'Request device and sharing capabilities only when a user needs them, then end their use predictably.', 'Browser features such as camera, location, clipboard, and sharing cross a trust boundary. Availability, permission state, user activation, and device conditions vary. A useful interface explains the action before asking, offers a manual path when access fails, and releases resources when work ends. This track uses field-case intake: an operator may attach a photo, add an approximate place, copy an identifier, or share a review link. Each step must still work when a prompt is dismissed or an API is absent.', ['web-tech/offline-and-device-capabilities', 'web-tech/browser-security-and-data-stewardship']),
    ('web-tech/overlays-scroll-and-mobile-viewport', 'Overlays, Scroll, and Mobile Viewport', 'Keep focused controls visible and usable across stacking, nested scrolling, gestures, and keyboards.', 'An interface can be structurally correct and still fail on a small screen. A menu clips inside an ancestor, a nested scroller traps the reader, a gesture competes with browser zoom, or a keyboard covers the save button. This track treats overlays and scrolling as interaction contracts. It uses a mobile case-review screen with a modal note editor, long activity feed, and optional reordering. Layout, focus, and input must work together across zoom, touch, keyboard, and restored navigation.', ['web-tech/css-layout-and-interface-systems', 'web-tech/complex-accessible-interactions']),
]

topics = [
    dict(hub=0, path='web-tech/permission-request-timing-and-manual-fallback', title='Permission Request Timing and Manual Fallback', summary='Ask for browser access at the point of use and preserve a useful manual path after denial.', sections=[
        ('Definition and boundary', 'A permission request is a user decision about a specific browser capability, not a normal prerequisite for loading a page. The browser may grant, deny, dismiss, or keep a request pending; the application must handle each result without treating the person as broken. Ask when the user has chosen the relevant action, explain what will happen to the data, and keep a manual route available. A permission-state query can help tailor copy, but support and state names differ between capabilities and browsers. The action itself remains the authoritative test.'),
        ('Working case', 'A field operator opens a case form on a shared tablet. The screen needs neither location nor camera until the operator selects Add place or Attach photo. Asking for both on page load would interrupt work and make the purpose unclear. If location is denied, the form accepts a typed district and landmark. If camera access fails, it accepts a file chosen through a normal input. The case can still be saved with an explicit Missing media status. A dismissed prompt leaves the action available for a later attempt.'),
        ('Implementation boundary', 'Separate feature detection, permission request, result handling, and cleanup. Do not assume a Permissions API query supports every capability or that a granted query state guarantees that the device is usable. A camera may be unplugged; an operating-system privacy setting may still block it. Catch request errors and map them to human actions rather than exposing only an exception name. Keep an in-progress state while a prompt is open, but do not spin forever: provide a cancel path that restores the form. The server validates every uploaded file and submitted location regardless of the browser path used.'),
        ('Cost and tradeoffs', 'Checking an in-memory capability flag is O(1); the real cost lies in user interruption, device startup, network uploads, and any background sensor work. Permission prompts are especially expensive when they appear before the person understands the benefit. A manual fallback adds interface and validation work but prevents a denied permission from blocking the whole task. Measure completion rate and time-to-complete for allowed, denied, dismissed, and unsupported paths. Do not count a granted prompt as a successful case submission.'),
        ('Failure and verification', 'A dashboard automatically asks for location on every visit. Operators who need only to read cases deny it, and the product then incorrectly disables the form. Move the request behind Add place, keep manual address entry, and test the four permission outcomes. Suspend the tab while the prompt is open, return later, and verify that buttons are neither duplicated nor stuck disabled. Test the same workflow with browser permissions pre-denied and with the relevant API removed. Confirm that every route still produces a valid server request.'),
        ('Decision note', 'Request only the capability needed for the chosen action. Treat denial as one expected branch of the workflow, with a useful manual result and a clear retry path. The interface may explain why access helps, but it must not promise that the browser will display a particular prompt or remember a decision for a fixed duration.')
    ], code='function captureChoice(capabilityAvailable, permissionResult) {\n  if (!capabilityAvailable || permissionResult !== "granted") return "manual-entry";\n  return "device-entry";\n}\nconsole.log(captureChoice(true, "denied"));\n// Output: manual-entry', mistakes=['Requesting every device permission when the page opens.', 'Assuming a permission-state query guarantees usable hardware.', 'Disabling the full form after a denied optional capability.'], related=['web-tech/offline-and-device-capabilities','web-tech/browser-security-and-data-stewardship','web-tech/responsive-interaction-contract']),
    dict(hub=0, path='web-tech/camera-microphone-capture-and-track-cleanup', title='Camera and Microphone Capture and Track Cleanup', summary='Start media capture after intent, stop every track, and separate preview from trusted upload.', sections=[
        ('Definition and boundary', 'Media capture creates live tracks tied to devices. Calling a capture API is the start of a resource lifecycle, not the completion of an attachment. The user should know whether the application asks for a photo, audio note, or both; a microphone request does not belong in a photo-only flow. Secure-context and browser support requirements apply, and the request can fail because of denial, missing hardware, competing use, or device policy. A stream that is no longer needed must have its tracks stopped. Removing a preview element alone does not necessarily release the camera.'),
        ('Working case', 'An operator selects Capture evidence for case 47 and sees a camera preview with Capture, Retake, and Cancel. On Capture, the app freezes an image for review and stops the live video track. On Retake, it starts a new capture attempt only when needed. On Cancel, route change, or a failed upload, it also stops all active tracks and removes any temporary object URL. A file-upload path remains visible for a device without camera access. The operator can inspect the chosen image before it leaves the tablet.'),
        ('Implementation boundary', 'Keep one owner for the current stream so lifecycle events cannot create competing captures. Once a stream resolves, check whether the screen is still active; a user may have navigated away while the browser prompt waited. If it is stale, stop the tracks immediately. Attach cleanup to cancel, unmount, successful capture, and error transitions. If switching cameras, stop old tracks before or after the replacement becomes ready according to the product’s continuity requirement. The captured file is untrusted input: enforce type, size, content inspection, and authorization on the server.'),
        ('Cost and tradeoffs', 'Stopping k tracks is O(k), usually a tiny count, but the device consumes power and may hold exclusive access while tracks remain active. Encoding a large image can use memory proportional to its pixel count and can block the main thread if handled poorly. Avoid keeping full-resolution previews and duplicate blobs longer than necessary. Measure preview startup, cancellation latency, memory after repeated retakes, and upload failure recovery. A camera-specific path should not make the case form depend on a live stream after an image has already been captured.'),
        ('Failure and verification', 'A capture component unmounts after route navigation, yet a late permission approval resolves and leaves the camera indicator on. Guard the resolution with a current-screen flag and stop the returned stream when stale. Another failure stops only the first video track while an accidentally requested audio track continues. Iterate every track. Repeat capture, retake, cancel, and route change fifty times in a test session and inspect device indicators and memory. Deny access at the browser and operating-system levels and verify that the file path remains usable.'),
        ('Decision note', 'Capture the minimum medium needed, release it at every terminal transition, and treat uploaded bytes as untrusted even if the browser produced them. A preview is a user interface state; authorization, storage limits, and scanning remain server responsibilities.')
    ], code='function stopCapture(stream) {\n  for (const mediaTrack of stream.getTracks()) mediaTrack.stop();\n  return stream.getTracks().every(mediaTrack => mediaTrack.readyState === "ended");\n}\nconst mediaTracks = [{ readyState: "live", stop() { this.readyState = "ended"; } }];\nconsole.log(stopCapture({ getTracks: () => mediaTracks }));\n// Output: true', mistakes=['Removing a preview without stopping tracks.', 'Requesting microphone access for a photo-only task.', 'Trusting browser-generated media without server validation.'], related=['web-tech/offline-and-device-capabilities','web-tech/browser-security-and-data-stewardship','web-tech/browser-storage-boundary']),
    dict(hub=0, path='web-tech/geolocation-accuracy-cancellation-and-retention', title='Geolocation Accuracy, Cancellation, and Retention', summary='Use location with a stated purpose, bounded waiting, accuracy context, and minimal retention.', sections=[
        ('Definition and boundary', 'A browser location is an estimate with an accuracy radius, time, and permission context. It is not proof that a person physically visited a site. A request can time out, be denied, return stale cached coordinates, or continue updating if a watch remains active. Decide whether the task needs one reading or ongoing updates. High-accuracy mode may use more battery and wait longer. The product should state what is stored and for how long, then collect the least precise location that still serves the case workflow.'),
        ('Working case', 'For case 47, an operator can Add approximate place. The UI first offers manual district entry and an optional Use current position button. A one-shot request has a bounded timeout; the result displays an accuracy description and allows correction before submission. If the browser returns a cached position older than the intake policy permits, the operator retries or enters a place manually. The case record stores a coarse place label when that is enough for dispatch, not raw latitude and longitude merely because the API supplied them.'),
        ('Implementation boundary', 'Set a deliberate timeout and maximum-age policy for a one-shot request, and show a cancel route even though cancellation of a pending one-shot call may depend on browser behavior. For continuous tracking, retain the watch identifier and call clearWatch on stop, route change, and account switch. Ignore late callbacks after the request is no longer relevant. Do not treat browser coordinates as a server-trusted authorization input. Validate the submitted value, constrain access to stored location, and remove precise coordinates when the approved retention purpose ends.'),
        ('Cost and tradeoffs', 'Processing each returned location is O(1), but a continuing watch creates repeated callbacks, battery use, and potential network writes over time. High accuracy can increase wait and energy cost while still failing indoors. A one-shot request reduces resource use, but its accuracy may be insufficient for a precise field operation. Choose based on the decision the user must make, not on the maximum precision the device can produce. Measure timeout, correction rate, number of active watches, and data retained per case.'),
        ('Failure and verification', 'An intake screen calls watchPosition for a single place label and never clears it. After the operator leaves, it keeps receiving positions and may write private movement data. Replace it with a one-shot request or clear the watch reliably. Another failure treats a location with a wide accuracy radius as an exact building. Display uncertainty and allow correction. Test denied permission, timeout, stale cache, late callbacks, account switch, and a device without location support. Confirm that deletion and export workflows include any stored coordinates under the chosen policy.'),
        ('Decision note', 'Match location precision, duration, and storage to the actual field decision. A manual place is a valid outcome, and an accuracy radius is part of the data rather than an inconvenient detail to hide.')
    ], code='function locationDecision(reading, maximumAgeMs, nowMs) {\n  if (!reading || nowMs - reading.timestamp > maximumAgeMs) return "manual-or-retry";\n  return reading.accuracyMeters > 320 ? "confirm-area" : "review-place";\n}\nconsole.log(locationDecision({ timestamp: 47000, accuracyMeters: 420 }, 9000, 52000));\n// Output: confirm-area', mistakes=['Using a continuous watch for a one-time place selection.', 'Presenting approximate coordinates as a verified address.', 'Retaining precise coordinates without a defined purpose.'], related=['web-tech/offline-and-device-capabilities','web-tech/browser-security-and-data-stewardship','web-tech/retention-inventory-and-expiry-workflows']),
    dict(hub=0, path='web-tech/clipboard-and-share-activation-fallbacks', title='Clipboard and Share Activation Fallbacks', summary='Handle user activation, capability gaps, and rejected share actions without losing the content.', sections=[
        ('Definition and boundary', 'Clipboard and native-share features are optional browser capabilities. A copy or share call may require a secure context, a recent user gesture, and browser-specific permission conditions. It can reject even when a method exists. The interface should preserve the material the person wanted to move: a visible, selectable case identifier or a normal review link remains useful after failure. Never read clipboard contents automatically simply to make a copy button look convenient. That crosses a separate privacy boundary and often has different permission rules.'),
        ('Working case', 'A reviewer opens case 47 and selects Copy case ID. The button initiates a write from the click handler and announces Copied only after the promise resolves. If the write rejects, the identifier stays visible in a selectable field with instructions to copy manually. The adjacent Share review action attempts the operating system’s share sheet only when available and requested. A dismissed share sheet leaves the page intact. A normal internal review link remains present for copying without requiring a native share target.'),
        ('Implementation boundary', 'Feature-detect each method immediately before use and keep calls tied to the originating activation when required. Do not await unrelated network requests before invoking a gated API. Catch rejection and distinguish cancellation from a product error when the platform exposes that distinction reliably. For a share payload, use a stable URL that the recipient can actually authorize; a private case link is not a public grant. Do not embed raw case notes into a share title or copied URL. The server still checks access when the link is opened.'),
        ('Cost and tradeoffs', 'Copying a short identifier is O(n) in the number of characters transferred and has negligible compute cost. The main cost is behavioral: false success messages make users paste stale clipboard content, and hidden fallback text makes failure hard to recover from. Native sharing can improve handoff on mobile but its available targets and result semantics differ by platform. Test not only that an API call resolves, but that a human can complete the handoff after rejection or cancellation. Avoid logging the copied private payload.'),
        ('Failure and verification', 'A handler awaits a case refresh before calling share, so the browser no longer recognizes the original user activation and rejects the request. Prepare the safe share payload before the click or invoke the capability directly from the click path. Another defect changes the label to Copied before the write promise settles. Wait for success. Test unsupported APIs, rejected writes, a dismissed share sheet, account changes, and a recipient without case access. The recipient should reach an access decision, not a leaked private record.'),
        ('Decision note', 'A browser convenience action should be an enhancement to visible, usable content. Confirm completion only after the capability succeeds, and keep server authorization on anything the copied or shared value points to.')
    ], code='function copyStatus(result) {\n  return result === "resolved" ? "copied" : "select-and-copy";\n}\nconsole.log(copyStatus("rejected"));\n// Output: select-and-copy', mistakes=['Showing success before the clipboard write resolves.', 'Waiting through another async operation before a user-activated share call.', 'Treating a shared private link as permission to read its target.'], related=['web-tech/browser-security-and-data-stewardship','web-tech/identity-and-application-security','web-tech/responsive-interaction-contract']),
    dict(hub=1, path='web-tech/stacking-context-top-layer-and-overlay-contract', title='Stacking Context, Top Layer, and Overlay Contract', summary='Choose modal, popover, or inline UI deliberately and avoid z-index fights across ancestors.', sections=[
        ('Definition and boundary', 'A stacking context orders its own descendants as a group. Raising one child’s z-index cannot necessarily put it above a sibling of an ancestor; transforms, opacity, positioning, and other properties can create new contexts. Clipping from an overflow ancestor is another independent limit. Browser top-layer primitives can place supported modal dialogs and popovers above ordinary document stacking and outside ancestor clipping, but their interaction models differ. A modal interrupts other interaction and needs a focus contract. A lightweight popover has different dismissal and accessibility requirements.'),
        ('Working case', 'The mobile case-review screen has an overflow-scrolling activity feed. An action menu rendered inside one feed row clips at the feed edge. Raising its z-index from 47 to 4700 changes nothing because the ancestor still clips it. Move the menu to an appropriate top-layer popover where supported, or place it in a controlled overlay root with positioning and dismissal behavior tested. The note editor is a true modal: opening it moves focus inside, blocks background interaction, supports Escape and a visible close control, then returns focus to the invoking action.'),
        ('Implementation boundary', 'First identify whether the control is an inline expansion, nonmodal popover, or modal dialog. Use the semantic primitive that matches the interaction. A top-layer placement solves painting and clipping, not every issue: anchor placement, focus order, outside-click policy, mobile keyboard behavior, and route teardown still need work. Do not place an interactive menu inside a container that is hidden from assistive technology when open. For a fallback overlay root, preserve reading and focus order, and test coordinate updates after scroll and resize.'),
        ('Cost and tradeoffs', 'Choosing a new stacking number is O(1) but often creates a long-term conflict because it does not explain the ancestor relationship. Measuring an anchor and repositioning on each scroll or resize can trigger layout work; batch reads and writes and stop listeners when the overlay closes. Browser-managed top-layer placement can remove much custom painting code, but support and exact behavior must be tested on target devices. Measure clipping, focus return, Escape behavior, and layout work during fast scrolling rather than judging only a desktop screenshot.'),
        ('Failure and verification', 'A team adds z-index 999999 to the menu. It still clips and appears behind a transformed sibling. Inspect ancestor stacking and overflow, then select a placement strategy. A second fix moves it to the document root but forgets to return focus when it closes, leaving keyboard users at the top of the page. Test pointer, keyboard, zoom, and assistive technology operation. Scroll the feed while the menu is open, resize the viewport, press Escape, leave the route, and ensure no detached overlay remains.'),
        ('Decision note', 'Treat an overlay as a behavior and focus contract with a painting strategy. Use top-layer semantics when they fit; solve clipping at the correct ancestor boundary rather than piling on arbitrary z-index values.')
    ], code='function overlayKind(blocksBackground, needsLightDismiss) {\n  if (blocksBackground) return "modal-dialog";\n  return needsLightDismiss ? "popover" : "inline-panel";\n}\nconsole.log(overlayKind(true, false));\n// Output: modal-dialog', mistakes=['Trying to escape ancestor clipping with a larger z-index.', 'Using a modal for a small optional menu.', 'Fixing paint order while leaving focus stranded.'], related=['web-tech/dialog-focus-and-interruption-boundary','web-tech/css-layout-and-interface-systems','web-tech/complex-accessible-interactions']),
    dict(hub=1, path='web-tech/scroll-containers-anchoring-and-chaining', title='Scroll Containers, Anchoring, and Chaining', summary='Keep content stable and reachable when nested regions scroll or load new material.', sections=[
        ('Definition and boundary', 'A page with nested scroll containers has several possible owners for wheel, touch, keyboard, and restored-position movement. Scroll chaining can pass movement from an inner container to an outer one; containment rules may change that behavior but vary by browser. Scroll anchoring may help keep visible content stable when earlier content changes height, yet it cannot correct every jump. Stable dimensions for media, predictable list updates, and a clear scroll owner matter more than a single CSS switch. Every scrollable region also needs a way for keyboard users to reach and operate it.'),
        ('Working case', 'A review page shows a long activity feed beside a note editor. New events arrive above the reviewer’s current reading position. The feed should not jump to the top or automatically force the latest event into view while the person is reading older material. Show a New events control and preserve an anchor record and offset when inserting rows. A note editor modal may need its own scrolling on a small screen, but background scroll must follow its chosen modal contract. On return from a detail route, restore the meaningful feed position only after the relevant rows are present.'),
        ('Implementation boundary', 'Prefer one primary page scroll when the layout permits it. If a nested region is necessary, label it, make it keyboard reachable, and give it a visible focus state. For inserted content, measure a stable item before the change and restore its position afterward, or rely on native anchoring when it passes target-browser tests. Reserve image space to avoid late layout shifts. Apply overscroll containment only where its effect is wanted; do not use it as the sole lock for a modal. Teardown scroll listeners and restore behavior when the route or overlay closes.'),
        ('Cost and tradeoffs', 'Appending one event is O(1) in a simple list, but maintaining thousands of DOM rows can cost O(n) memory and expensive layout. Windowing lowers DOM cost but complicates anchoring and screen-reader access, so test the reading workflow before optimizing. Measuring positions around every update may force layout; group reads before writes and avoid repeated measurements inside animation frames. Track unexpected scroll displacement, keyboard reachability, and the number of times users must fight automatic movement. A quick screenshot cannot reveal a scroll trap.'),
        ('Failure and verification', 'An activity feed receives a new image whose height was unknown, shifting the reviewer’s current event out of view. Reserve dimensions or an aspect ratio and preserve the reading anchor. Another implementation hides page overflow when a modal opens but never restores it after navigation, leaving the page frozen. Test long feeds, delayed media, zoom, keyboard scrolling, touch momentum, modal open and close, route return, and a new-event burst. Verify that the reviewer can reach the editor’s submit control without losing the feed context.'),
        ('Decision note', 'Give each scroll action an intentional owner and preserve the reader’s place. Native scroll features are useful, but stable layout and tested interaction determine whether the contract holds.')
    ], code='function shouldAutoFollow(distanceFromBottomPx, userReadingHistory) {\n  return !userReadingHistory && distanceFromBottomPx <= 48;\n}\nconsole.log(shouldAutoFollow(620, true));\n// Output: false', mistakes=['Making a nested region scrollable without keyboard access.', 'Auto-scrolling a reader who is inspecting older events.', 'Using overscroll containment as the entire modal scroll lock.'], related=['web-tech/route-scroll-and-focus-restoration','web-tech/css-layout-and-interface-systems','web-tech/live-update-reconnect-and-order']),
    dict(hub=1, path='web-tech/pointer-gesture-touch-action-and-alternate-control', title='Pointer Gesture, Touch Action, and Alternate Control', summary='Keep custom gestures compatible with browser panning and equivalent button or keyboard actions.', sections=[
        ('Definition and boundary', 'Pointer events unify several input types, but a finger gesture also competes with browser panning and zoom. CSS touch-action tells the browser which direct-manipulation gestures it may handle. Disabling them broadly can remove expected navigation or accessibility behavior. Pointer capture can keep a drag stream coherent, but the application must handle pointercancel, release, and route teardown. A custom gesture should be an optional way to complete a task, with a visible non-drag control that works by keyboard, switch device, and touch.'),
        ('Working case', 'A reviewer orders three evidence cards in case 47. Dragging a card on a small phone can conflict with vertical page scrolling. The interface offers Move up and Move down buttons on each card, then adds drag as an optional shortcut for devices where it is usable. The buttons update order and announce the result; the drag path uses the same reorder operation. Only the drag handle restricts touch gestures, and the rest of the card remains scrollable. If the pointer is canceled by a browser gesture, the preview resets without saving a half-complete order.'),
        ('Implementation boundary', 'Keep committed order separate from a temporary drag preview. On pointerdown, record the original order and capture the pointer only when a drag actually begins. On pointerup, validate the target position and commit through the same server mutation as button controls. On pointercancel, Escape, or route leave, restore the original view. Do not use a gesture as a hidden authorization route: the server validates the requested position and current record version. Consider touch target size, zoom, reduced motion, and a text announcement of the new position.'),
        ('Cost and tradeoffs', 'A reorder in an array of n cards can cost O(n) to create the new order, while each pointermove should avoid expensive full-list work. Coalesce visual updates in animation frames and do not write to the server on every movement. Restricting touch-action on a narrow handle preserves page panning elsewhere, though it may make the drag target smaller. Measure accidental drags, canceled gestures, keyboard completion, and movement latency. The simpler button path is also an important recovery mechanism after a drag fails.'),
        ('Failure and verification', 'A developer sets touch-action none on the entire feed to make drag smooth. Users can no longer pan normally over card content, and some zoom workflows suffer. Restrict the declaration to a deliberate handle or remove drag. Another defect commits a preview when pointercancel fires during a scroll. Treat cancellation as rollback. Test mouse, touch, pen, keyboard, switch-style sequential focus, browser zoom, and an interrupted gesture. Confirm that both drag and buttons produce the same validated final order.'),
        ('Decision note', 'Preserve native page movement and provide an equivalent discrete control. A gesture is useful only when its cancellation and accessibility paths are as clear as its happy path.')
    ], code='function moveEvidence(evidenceIds, fromIndex, toIndex) {\n  const reorderedIds = [...evidenceIds];\n  const [movedId] = reorderedIds.splice(fromIndex, 1);\n  reorderedIds.splice(toIndex, 0, movedId);\n  return reorderedIds;\n}\nconsole.log(moveEvidence([47, 62, 89], 2, 1).join(","));\n// Output: 47,89,62', mistakes=['Disabling touch panning over an entire content region.', 'Saving a partial order after pointercancel.', 'Making drag the only way to reorder.'], related=['web-tech/complex-accessible-interactions','web-tech/data-table-versus-interactive-grid','web-tech/responsive-interaction-contract']),
    dict(hub=1, path='web-tech/visual-viewport-keyboard-and-focused-input', title='Visual Viewport, Keyboard, and Focused Input', summary='Keep active inputs and actions reachable when the on-screen keyboard changes visible space.', sections=[
        ('Definition and boundary', 'The layout viewport and the visible portion of a mobile page are not always the same. An on-screen keyboard may shrink or move the visual viewport while the layout viewport retains its dimensions; behavior differs across browsers and device settings. A fixed footer can cover the focused field, and a modal that fit before typing can lose its close or save action. The interface should keep the active control and its label visible, allow content to scroll, and avoid assuming one keyboard height or operating-system layout.'),
        ('Working case', 'A reviewer opens a modal note editor on a phone and focuses the last field. The keyboard appears, leaving only part of the editor visible. The modal content scrolls within the remaining space, while the save action stays reachable without covering entered text. When the keyboard closes, the layout returns without a large blank gap. If the phone is zoomed or rotated, the editor still exposes a close control and focus remains in the modal. A return to the activity feed restores focus to the edit trigger, not a hidden footer.'),
        ('Implementation boundary', 'Start with flexible block sizing, safe-area-aware spacing, and a scrollable modal body. Use visual-viewport measurements only when the target-browser behavior requires them; detect the API and clean up resize and scroll listeners. Read measurements in a batched step and avoid changing many layout properties for every keyboard animation frame. Do not force scroll on every input event, because it can fight the browser’s own focus scrolling. Test with hardware keyboards too: a missing on-screen keyboard should not leave an artificially short editor.'),
        ('Cost and tradeoffs', 'Reading a viewport dimension is O(1), but repeatedly measuring layout and writing heights during rapid resize can trigger costly recalculation. CSS-based flexible sizing reduces script work but may need browser-specific verification. An always-fixed action bar is visually convenient until it obscures the active field or traps the user; making the content scrollable may be safer. Measure field visibility, action reachability, layout shifts, and focus return under keyboard open, close, rotation, zoom, and route transition. Do not infer success from one emulator screenshot.'),
        ('Failure and verification', 'A modal sets height to a fixed 620 pixels and pins Save to the bottom of the layout viewport. On a small phone the keyboard covers Save, and the modal body cannot scroll. Replace the fixed height with a bounded flexible layout and test the visible region while typing. Another fix listens to visualViewport resize but never removes the listener, so repeated modal openings cause multiple competing measurements. Open and close repeatedly, rotate, zoom, connect a hardware keyboard, and test a browser without visualViewport support. Confirm focus is never sent behind the modal.'),
        ('Decision note', 'Design for the visible space the person has while typing. Use browser viewport signals as measured input, with a CSS-first fallback and a focus contract that survives keyboard changes.')
    ], code='function usableEditorHeight(visibleHeightPx, reservedControlsPx) {\n  return Math.max(240, visibleHeightPx - reservedControlsPx);\n}\nconsole.log(usableEditorHeight(510, 126));\n// Output: 384', mistakes=['Assuming keyboard height is constant across devices.', 'Fixing the action bar over the active field.', 'Leaving visual-viewport listeners active after the editor closes.'], related=['web-tech/dialog-focus-and-interruption-boundary','web-tech/route-scroll-and-focus-restoration','web-tech/responsive-interaction-contract']),
]

assert len(hubs) == 2 and len(topics) == 8
for number, (path, title, summary, overview, bridges) in enumerate(hubs):
    assert path not in by_path
    entry = copy.deepcopy(by_path['web-tech/production-signals-and-incident-decisions'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + path)), path=path, title=title, summary=summary, sort_order=2600 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
    entry['data'] = {'subject_root':'web-tech/web-technology','section_path':path,'content_format':'html','seo_ready':False,'modules':[],'resource_tabs':[{'title':'Web Development','path':'web-tech/web-technology'},{'title':'Projects','path':'web-tech/web-technology/project'},{'title':'Quizzes','path':'web-tech/quizzes'}]}
    entries.append(entry)
    by_path[path] = entry

for number, topic in enumerate(topics):
    path = topic['path']
    assert path not in by_path
    subprocess.run(['node', '--check', '--input-type=module'], input=topic['code'], text=True, capture_output=True, check=True)
    entry = copy.deepcopy(by_path['web-tech/trace-context-across-request-and-job'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + path)), path=path, title=topic['title'], summary=topic['summary'], sort_order=2610 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
    hub_path = hubs[topic['hub']][0]
    related = [hub_path] + [item['path'] for item in topics if item['hub'] == topic['hub'] and item['path'] != path] + topic['related']
    body = paragraph(topic['sections'][0][1])
    for heading, content in topic['sections'][1:3]:
        body += '<h2>' + html.escape(heading) + '</h2>' + paragraph(content)
    body += '<pre><code class="language-javascript">' + html.escape(topic['code'], quote=False) + '</code></pre>'
    for heading, content in topic['sections'][3:]:
        body += '<h2>' + html.escape('Failure trace' if heading == 'Failure and verification' else heading) + '</h2>' + paragraph(content)
    body += '<h2>Verification</h2><ul><li>' + html.escape('Complete the primary case with the capability available and with it denied or absent.') + '</li><li>' + html.escape('Interrupt the interaction during its pending state and confirm no stale resource, focus, or scroll state remains.') + '</li><li>' + html.escape('Check that server authorization and validation still hold after the browser interaction.') + '</li></ul>'
    body += '<h3>Common Mistakes</h3><ul>' + ''.join('<li>' + html.escape(item) + '</li>' for item in topic['mistakes']) + '</ul>'
    body += '<h2>Connected lessons</h2><p>' + '; '.join(link(item) for item in related) + '.</p>'
    entry['body'] = body
    entry['data'] = {'subject_root':'web-tech/web-technology','section_path':hub_path,'content_format':'html','seo_ready':False,'kind':'tutorial','author_path':'authors/aitrove-editorial','reading_minutes':max(6, round(len(re.findall(r'\b\w+\b', re.sub(r'<[^>]+>', ' ', body))) / 155)), 'related':related}
    entries.append(entry)
    by_path[path] = entry

for number, (path, title, summary, overview, bridges) in enumerate(hubs):
    group = [item for item in topics if item['hub'] == number]
    entry = by_path[path]
    entry['data']['modules'] = [{'title':title,'summary':summary,'lessons':[item['path'] for item in group]}]
    entry['body'] = paragraph(overview) + '<h2>Topics in this track</h2><ul>' + ''.join('<li>' + link(item['path']) + ' — ' + html.escape(item['summary']) + '</li>' for item in group) + '</ul>'
    entry['body'] += '<h2>Prerequisite paths</h2><p>' + '; '.join(link(item) for item in bridges) + '.</p>'
    entry['body'] += '<h2>Neighbor track</h2><p>' + link(hubs[1 - number][0]) + '.</p>'

root_entry = by_path['web-tech/web-technology']
for number, (path, title, summary, _, _) in enumerate(hubs):
    group = [item for item in topics if item['hub'] == number]
    root_entry['data']['modules'].append({'title':title,'summary':summary,'lessons':[path] + [item['path'] for item in group]})
    root_entry['body'] += '<h2>' + link(path) + '</h2>' + paragraph(summary) + '<ul>' + ''.join('<li>' + link(item['path']) + ' — ' + html.escape(item['summary']) + '</li>' for item in group) + '</ul>'
root_entry['updated_at'] = stamp

crosslinks = {
    'web-tech/offline-and-device-capabilities':[hubs[0][0],topics[0]['path'],topics[2]['path']],
    'web-tech/browser-security-and-data-stewardship':[topics[1]['path'],topics[3]['path']],
    'web-tech/css-layout-and-interface-systems':[hubs[1][0],topics[4]['path']],
    'web-tech/dialog-focus-and-interruption-boundary':[topics[4]['path'],topics[7]['path']],
    'web-tech/route-scroll-and-focus-restoration':[topics[5]['path'],topics[7]['path']],
    'web-tech/complex-accessible-interactions':[topics[6]['path']],
}
for path, targets in crosslinks.items():
    entry = by_path[path]
    entry['body'] += '<h2>Further connections</h2><p>' + '; '.join(link(item) for item in targets) + '.</p>'
    entry['updated_at'] = stamp

fixture.write_text(json.dumps(entries, ensure_ascii=False, indent=2) + '\n')
print(json.dumps({'new_hubs':len(hubs), 'new_lessons':len(topics)}))
